# Execute only the actual new fusion helper with a standard-library tensor
# adapter. This checks algebra/indexing, not torch, autocast or gradients.
class Tensor:
 dtype='float64'
 device=type('Device',(),{'type':'cpu'})()
 def __init__(self,data): self.data=data
 def flatten(self,start):
  assert start==1
  def flat(x):
   return [v for row in x for v in flat(row)] if x and isinstance(x[0],list) else x
  return Tensor([flat(row) for row in self.data])
 def float(self): return self
 def to(self,dtype): return self
 def _binary(self,other,f):
  data=other.data if isinstance(other,Tensor) else [[other]*len(row) for row in self.data]
  return Tensor([[f(x,y) for x,y in zip(a,b)] for a,b in zip(self.data,data)])
 def __add__(self,x): return self._binary(x,lambda a,b:a+b)
 __radd__=__add__
 def __mul__(self,x): return self._binary(x,lambda a,b:a*b)
 __rmul__=__mul__
class Torch:
 @staticmethod
 def tanh(x): return Tensor([[math.tanh(v) for v in row] for row in x.data])
 @staticmethod
 def autocast(**kw): return nullcontext()
def linear(w,b):
 return lambda x: Tensor([[sum(a*v for a,v in zip(row,inp))+bias for row,bias in zip(w,b)] for inp in x.data])
def silu(x): return Tensor([[v/(1+math.exp(-v)) for v in row] for row in x.data])
