run=ns['_contextual_residual']; rng=random.Random(20261109); count=0
for batch in [1,2,7]:
 for mode in ['cross','additive']:
  for zero_context in [False,True]:
   for iteration in range(20):
    obj=type('TestModel',(),{})(); obj.context_mode=mode
    wh=[[rng.uniform(-1,1) for _ in range(5)] for _ in range(3)]
    bh=[rng.uniform(-1,1) for _ in range(3)]
    wc=[[0.0 if zero_context else rng.uniform(-1,1) for _ in range(4)] for _ in range(3)]
    bc=[0.0 if zero_context else rng.uniform(-1,1) for _ in range(3)]
    wo=[[rng.uniform(-1,1) for _ in range(3)] for _ in range(4)]
    bo=[rng.uniform(-1,1) for _ in range(4)]
    obj.feedback_residual=[linear(wh,bh),silu,linear(wo,bo)]; obj.feedback_context=linear(wc,bc)
    r=Tensor([[rng.uniform(-3,3) for _ in range(5)] for _ in range(batch)])
    static=Tensor([[[rng.uniform(-2,2) for _ in range(2)] for _ in range(2)] for _ in range(batch)])
    actual=run(obj,r,static).data
    for row in range(batch):
     h=[v/(1+math.exp(-v)) for v in [sum(a*b for a,b in zip(w,r.data[row]))+bias for w,bias in zip(wh,bh)]]
     x=[v for field in static.data[row] for v in field]
     c=[math.tanh(sum(a*b for a,b in zip(w,x))+bias) for w,bias in zip(wc,bc)]
     fused=[a+b+(a*b if mode=='cross' else 0) for a,b in zip(h,c)]
     expected=[sum(a*b for a,b in zip(w,fused))+bias for w,bias in zip(wo,bo)]
     assert all(math.isfinite(v) for v in actual[row])
     assert max(abs(a-b) for a,b in zip(actual[row],expected))<1e-12
     if zero_context:
      source=obj.feedback_residual[2](obj.feedback_residual[1](obj.feedback_residual[0](r))).data[row]
      assert actual[row]==source
    count+=1
# Direct mixed finite contrast: cross has interaction; additive has none.
